def transform(grid):
    out = [row[:] for row in grid]
    cells = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v != 0]
    if not cells:
        return out
    r0 = min(r for r, c, v in cells)
    r1 = max(r for r, c, v in cells)
    c0 = min(c for r, c, v in cells)
    c1 = max(c for r, c, v in cells)
    colors = {v for r, c, v in cells}
    outer = grid[r0][c0]
    inner = next((v for v in colors if v != outer), None)
    if inner is None:
        return out
    core = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == inner]
    ir0, ir1 = min(r for r, c in core), max(r for r, c in core)
    ic0, ic1 = min(c for r, c in core), max(c for r, c in core)
    ih, iw = ir1-ir0+1, ic1-ic0+1
    if ih == iw:
        thickness = ih
    else:
        thickness = min(ir0-r0, r1-ir1, ic0-c0, c1-ic1)
    for r in range(max(0, r0-thickness), min(len(grid), r1+thickness+1)):
        for c in range(max(0, c0-thickness), min(len(grid[0]), c1+thickness+1)):
            if grid[r][c] == 0:
                out[r][c] = inner
    return out
